from wd_common import *
i=0
Z=lambda q,a:[('z',q),('b',a)]
def plate5(): return '<ellipse rx="34" ry="9" fill="#c9a227"/>'+''.join(g(x,-6,.35,flame()) for x in (-22,-11,0,11,22))
def camph(): return '<ellipse rx="22" ry="7" fill="#c9a227"/><rect x="-8" y="-12" width="16" height="10" fill="#f4f1ea"/>'+g(0,-12,.5,flame())
def bellf(): return '<path d="M-14 0 q0 -30 14 -30 q14 0 14 30z" fill="#c9a227"/><rect x="-2" y="-44" width="4" height="14" fill="#a8841f"/><circle cy="4" r="4" fill="#a8841f"/>'
def arc(cx,cy,r): return f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>'
def shrine2(): return '<rect x="-60" y="-120" width="120" height="120" fill="#3a2a1a"/><path d="M-76 -120 L0 -170 L76 -120z" fill="#7a3b1f"/>'
fw=foreword(i,['At the end of almost every Hindu worship, at home or in a temple, someone lifts a lamp and waves it in circles before the god while a bell rings and people sing. This is <b>ārati</b>. Then the plate comes round, and everyone passes their palms over the flame and touches their eyes.',
 'This first part of <b>Why Do We…</b> explains the name, where ārati sits in pūjā, what is waved and how, why camphor, what the gesture of receiving means, the ārati done for people, the songs and the times of day, and the readings teachers give it.',
 'Ārati at home is part of '+L('/why-do-we/home-puja/','Home Pūjā')+'. Next in this series: '+L('/why-do-we/tilaka/','tilaka')+'.'],Z('Is ārati the most important part of pūjā?','It is the most visible. Every part matters; ārati is where the whole room joins in.'))
gl=glance([('Name','Ārati, from ārātrika; also nīrājana'),('What','Waving lit lamps (and other offerings) before the deity'),('Place in pūjā','One of the upacāras, the services offered to the god; usually near the end'),('Lamps','Ghee lamps of one, five or many wicks; camphor'),('Movement','Clockwise circles before the deity'),('Sound','Bell, conch, drums, songs'),('Receiving','Palms over the flame, then to the eyes and head'),('Times','Morning (maṅgaḷārati), evening, night'),('For people','Ārati for brides, grooms, guests, children'),('Meaning','Seeing the god in light; offering light back')],
 S('A priest waves a five-wick lamp before a deity while a devotee rings a bell',g(380,215,1.3,shrine2())+g(380,200,1.1,god('#e0a800'))+arc(380,140,50)+g(250,215,1.5,person('#f4f1ea'))+g(290,150,1,plate5())+g(140,215,1.4,person('#c0392b'))+g(170,150,.8,bellf()),'#20243a',215),Z('Why at the end?','The god has been bathed, dressed and fed. Now we look at him in the light.'),'Light waved, <b>god seen</b>.')
name=reading('name','THE NAME','Ārātrika and nīrājana',S('A dark night sky and a single lamp lighting a face',g(280,200,2,lamp())+g(450,60,1,moon())+g(120,215,1.4,person('#e0a800')),'#20243a',215),
 ['<b>Ārātrika.</b> Ārati comes from the Sanskrit <b>ārātrika</b>. It is commonly explained through rātri, “night”: light that drives away darkness. (Common explanation; etymologies differ.)','<b>Nīrājana.</b> The formal Sanskrit name in pūjā manuals is <b>nīrājana</b>, the waving of lights before the deity.','<b>Regional names.</b> In Kannaḍa homes it is often <b>maṅgaḷārati</b>, the auspicious ārati.','<b>One word, many forms.</b> The name covers a single camphor flame at home and a great temple ārati with many lamps.','<b>Both meanings.</b> Light offered to the god, and light by which the god is seen.'],Z('So ārati means “against the night”?','That is the usual explanation. Whatever the root, the act is plain: bring light.'),'Light <b>against the dark</b>.')
place=reading('place','IN THE PŪJĀ','Where ārati comes',svg(560,160,'Steps of a pūjā in a row ending with ārati','<rect width="560" height="160" fill="#fff3cf"/>'+tl_strip([('invite','āvāhana'),('bathe','abhiṣeka'),('dress','vastra'),('incense','dhūpa'),('lamp','dīpa'),('food','naivedya'),('light','nīrājana')],560,160)),
 ['<b>Upacāras.</b> Pūjā is a set of services (upacāras) offered to the god as to an honoured guest: welcome, seat, water, bath, clothes, sandal, flowers, incense, lamp, food.','<b>Sixteen.</b> The fullest common form has sixteen, the <b>ṣoḍaśopacāra</b> pūjā; shorter forms have five.','<b>After food.</b> Nīrājana usually follows the food offering (naivedya), near the close.','<b>Dīpa and nīrājana.</b> The lamp (dīpa) shown earlier is a single offering; nīrājana is the waving that crowns the pūjā.','<b>Lists differ.</b> The order and number vary between manuals and traditions.'],Z('Lamp twice?','First shown, then waved. One is courtesy, the other celebration.'),'The crown <b>of the pūjā</b>.')
what=cards('what','WHAT IS WAVED','Lamps and more',fig_row('A single lamp, a five-wick plate, camphor, a many-tiered lamp and a conch',[(lamp(),1),(plate5(),1),(camph(),1.2),('<path d="M-6 0 v-60 h12 v60z" fill="#c9a227"/>'+''.join(g(0,-y,.3,flame()) for y in (10,25,40,55)),1),('<path d="M-16 0 q-10 -20 6 -30 q20 -6 22 14 q-4 16 -28 16z" fill="#f4f1ea"/>',1.2)],['one wick','pañcārati','camphor','tiered lamp','conch'],gy=150),
 [('🪔','Ghee lamp','One wick or many; ghee is preferred, oil also used.'),('✋','Pañcārati','Five wicks, often linked to the five elements. (Interpretation.)'),('⚪','Camphor','Karpūra, a clean white flame.'),('🛕','Many-tiered lamps','Temples use lamps of many levels, shaped like serpents, pots or trees.'),('🐚','Not only fire','In full temple nīrājana, water in a conch, cloth, flowers and a whisk may also be waved.'),('🔔','With it','Bell, conch and song.')],None,'Light first, <b>then the rest</b>.',intro='What is waved depends on the home, the temple and the occasion.')
how=reading('how','HOW IT IS WAVED','Circles before the god',S('A hand moving a lamp in clockwise circles from feet to face to whole form',g(280,215,1.6,shrine2())+g(280,200,1.4,god('#e0a800'))+arc(280,190,22)+arc(280,150,20)+arc(280,100,24)+arc(280,140,70),'#20243a',230),
 ['<b>Clockwise.</b> The lamp moves in clockwise circles, the auspicious direction.','<b>A common pattern.</b> A widely taught pattern waves the lamp at the feet, then the navel, then the face, then over the whole form, with a set number of turns for each. (Practices differ.)','<b>Right hand.</b> The lamp is held in the right hand; the left often rings the bell.','<b>Steady.</b> The movement is slow and full, so the god’s form is lit part by part.','<b>Close.</b> The plate is then set down or carried to the devotees.'],Z('What if I wave anticlockwise?','The god will forgive you. The tradition says clockwise; learn it.'),'Feet, heart, face, <b>all of him</b>.')
recv=reading('receive','RECEIVING THE LIGHT','Palms over the flame',S('Devotees cupping their palms over a flame and touching their eyes',g(280,200,1.4,plate5())+g(170,215,1.4,person('#c0392b'))+g(390,215,1.4,person('#1d4f8a'))+'<path d="M190 150 q30 -20 60 30 M370 150 q-30 -20 -60 30" stroke="#e8c3a0" stroke-width="8" fill="none"/>','#20243a',215),
 ['<b>The gesture.</b> When the plate comes round, people pass their cupped hands over the flame and bring them to their eyes and head.','<b>Taking the blessing.</b> The light has touched the god; the hands carry it back to the devotee.','<b>An offering in the plate.</b> Many put a coin or note in the ārati plate; it goes to the priest or the temple.','<b>Only the hands.</b> No one blows out an ārati flame; it is allowed to burn out or is put out by hand.','<b>For the sick.</b> Families often carry the blessing home to those who could not come.'],Z('Why the eyes?','The eyes have just seen the god. Touch them with his light.'),'Take the light <b>home in your hands</b>.')
camph=reading('camphor','WHY CAMPHOR','A flame that leaves nothing',S('A block of camphor burning to nothing on a plate',g(140,200,2,camph())+g(280,200,2,'<ellipse rx="22" ry="7" fill="#c9a227"/><rect x="-5" y="-6" width="10" height="5" fill="#f4f1ea"/>'+g(0,-6,.4,flame()))+g(420,200,2,'<ellipse rx="22" ry="7" fill="#c9a227"/>'),'#20243a',215),
 ['<b>Bright and clean.</b> Camphor (karpūra) burns with a bright white flame and a fragrance.','<b>No residue.</b> It burns away almost completely, leaving no ash.','<b>The reading.</b> Teachers often say: so should the ego burn away before God, leaving nothing behind. (Interpretation.)','<b>Practical.</b> Easy to light, needs no wick, quick to finish at the end of worship.','<b>Pure camphor.</b> Many prefer edible-grade camphor (pacca karpūra) for worship, as used in temple sweets.'],Z('So the camphor is me?','Your pride, says the teacher. Watch it go.'),'Burn <b>and leave no ash</b>.')
dark=reading('sanctum','LIGHT IN THE SANCTUM','Seeing the god',S('A dark inner shrine where only a lamp lights the stone image',g(280,215,2,shrine2())+g(280,200,1.5,god('#7a6a5a'))+g(240,130,.9,flame())+'<circle cx="240" cy="120" r="70" fill="#e0a800" opacity=".18"/>','#0e0e16',230),
 ['<b>Dark by design.</b> The inner sanctum (garbhagṛha) of a temple is small and dark, lit only by lamps.','<b>Darśana.</b> Worship centres on darśana, seeing the deity and being seen. In the dark, the waved lamp shows the image part by part.','<b>A plain origin.</b> This is a likely practical root of ārati: to let worshippers see the god. (Common explanation.)','<b>The moment.</b> In great temples the curtain opens for ārati and the crowd sees the god lit up all at once.','<b>See more.</b> How a temple is laid out: '+L('/temples-of-india/how-to-read-a-hindu-temple/','How to read a Hindu temple')+'.'],Z('Couldn’t they just add windows?','Then it would be a hall. The dark makes the light mean something.'),'In the dark, <b>light shows the god</b>.')
people=reading('people','ĀRATI FOR PEOPLE','Brides, guests and children',S('Women wave a plate of red water before a bride and groom at a doorway',g(280,200,1.2,'<rect x="-60" y="-130" width="120" height="130" fill="#7a3b1f"/><rect x="-44" y="-114" width="88" height="114" fill="#3a1a0a"/>')+g(250,215,1.2,person('#c0392b'))+g(310,215,1.2,person('#f4f1ea'))+g(150,215,1.2,person('#e0a800'))+g(410,215,1.2,person('#2a9d6f'))+g(200,160,.8,'<ellipse rx="26" ry="8" fill="#c9a227"/><ellipse cy="-4" rx="18" ry="5" fill="#d02a2a"/>'),'#fff3cf',215),
 ['<b>Not only gods.</b> Ārati is also done for people at important moments.','<b>Red water.</b> In Karnataka and much of the south, women wave a plate of water reddened with turmeric and lime (or kuṅkuma), sometimes with a lamp, before a bride and groom, a new mother and baby, or someone returning from a journey.','<b>Dṛṣṭi.</b> It is said to ward off the evil eye; the water is then thrown away outside. (Popular belief.)','<b>Festivals.</b> Children get ārati on birthdays and festivals in many homes.','<b>Respect.</b> A great guest or teacher may be welcomed with ārati.'],Z('Why throw the water away?','Whatever bad it caught is thrown out with it, so the saying goes.'),'Light <b>for the honoured guest</b>.')
times=cards('times','THE DAY’S ĀRATIS','From waking to sleep',fig_row('Sunrise, noon sun, sunset and moon',[(sun_ if False else '<circle r="16" fill="#f0b030"/><path d="M-30 4 h60" stroke="#c98a2a" stroke-width="3"/>',1.2),('<circle r="18" fill="#f0c030"/>',1.2),('<circle r="16" fill="#e06030"/><path d="M-30 4 h60" stroke="#7a3b1f" stroke-width="3"/>',1.2),(moon(),1)],['morning','noon','evening','night'],gy=150),
 [('🌅','Maṅgaḷārati','At dawn, waking the god; in many temples the first ārati of the day.'),('☀️','Midday','After the noon food offering.'),('🌇','Sandhyā ārati','At dusk, when the lamps are lit; the most attended at home.'),('🌙','Śayana ārati','At night, before the god rests.'),('🎉','Festivals','Extra āratis on festival days and processions.'),('🏠','At home','Most homes keep at least the evening ārati.')],None,'Light <b>through the day</b>.',intro='Temple schedules differ; these are the common points of the day.')
songs=reading('songs','THE SONGS','Singing while the lamp turns',S('A family singing together while the lamp is waved; a drum and a bell',g(280,200,1.2,plate5())+''.join(g(100+k*90,215,1.1,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a'][k])) for k in range(5))+g(500,160,.8,bellf()),'#fff3cf',215),
 ['<b>Ārati songs.</b> Each region and deity has ārati songs; families learn them by heart.','<b>Om Jaya Jagadīśa Hare.</b> The best known across north India was composed in the 19th century by Śraddhārām Phillauri.','<b>In Karnataka.</b> Kannaḍa homes sing maṅgaḷārati songs, many from the Haridāsa tradition.','<b>Sanskrit.</b> Temples often recite Sanskrit verses at nīrājana; some sing Karpūragauraṃ for Śiva.','<b>Sound matters.</b> Bell, conch and clapping fill the room; see '+L('/why-do-we/bell/','why we ring the bell')+'.'],Z('Do I need to know the songs?','Clap and listen. You will know them by the tenth time.'),'Everyone <b>sings at ārati</b>.')
st=story('story','AN EVENING ĀRATI','Ammu learns to wave the lamp',strip('Three panels: grandmother lights the lamp; the girl waves it with guidance; the family takes the light',
 [('<rect width="144" height="190" fill="#20243a"/>'+g(50,180,.8,person('#f4f1ea'))+g(100,150,.7,lamp()),'#20243a'),
  ('<rect width="144" height="190" fill="#20243a"/>'+g(60,180,.7,person('#c0392b'))+g(100,120,.5,plate5())+'<circle cx="100" cy="120" r="24" fill="none" stroke="#e0a800" stroke-width="2" stroke-dasharray="5 4"/>','#20243a'),
  ('<rect width="144" height="190" fill="#20243a"/>'+g(40,180,.6,person('#1d4f8a'))+g(100,180,.6,person('#2a9d6f'))+g(72,130,.5,plate5()),'#20243a')],['the lamp','the circles','the light']),'An evening at home (an illustrative story).',
 ['Ajji lights the camphor and gives the plate to Ammu: “Slowly. Round, like the clock.”','Ammu waves it at the feet of the little Kṛṣṇa, then his face, then all of him, while her brother rings the bell.','Then everyone holds out their hands. “Now you have given him light,” says Ajji, “and he gives it back.”'])
mean=reading('meaning','WHAT IT MEANS','Readings of the teachers',S('A lamp before a god, and the same lamp reflected in a devotee’s heart',g(160,200,1.4,god('#e0a800'))+g(280,170,1.2,plate5())+g(400,215,1.5,person('#c0392b'))+g(400,150,.5,flame()),'#20243a',215),
 ['<b>Seeing.</b> Ārati lets us see the god clearly, at least for a moment. (Common teaching.)','<b>Returning light.</b> The sun and fire are the god’s light; we offer a little of it back. (Interpretation.)','<b>All of the god.</b> Lighting each part in turn teaches attention: feet, heart, face, whole. (Interpretation.)','<b>Ego as camphor.</b> The flame that leaves no ash is the self that leaves no pride. (Interpretation.)','<b>Together.</b> Ārati turns private worship into a shared moment: everyone sees, sings and receives.'],Z('Which meaning is right?','All of them help. Pick the one that keeps your hands steady.'),'See, offer, <b>receive</b>.')
myth=reading('myths','COMMON QUESTIONS','What tradition says and does not say',S('A question mark beside a lamp and an open book',g(160,200,2,lamp())+'<text x="300" y="150" font-size="90" fill="#1d4f8a" font-family="serif">?</text>'+g(440,200,1.4,'<rect x="-40" y="-50" width="80" height="50" fill="#fff8e7"/><path d="M0 -50 v50" stroke="#7a3b1f"/>'),'#fff3cf',215),
 ['<b>Must I have a priest?</b> No. Anyone may do ārati at home.','<b>Ghee or oil?</b> Ghee is preferred in most traditions; oil is acceptable.','<b>Can I blow it out?</b> Custom says no; let it burn out or snuff it with the hand or a leaf.','<b>Electric lamps?</b> Some temples use them for light, but ārati itself is done with a flame.','<b>Women during periods?</b> Customs differ between families and communities; this site does not prescribe.'],Z('So there are no strict rules?','There are customs. Learn your family’s, respect the temple’s.'),'Custom, <b>not fear</b>.')
endp=end(i,['<b>Name.</b> Ārati (ārātrika), nīrājana: waving lights before the god.','<b>Place.</b> An upacāra near the end of pūjā.','<b>How.</b> Clockwise circles, feet to face to whole form; bell and song.','<b>Receiving.</b> Palms over the flame, then to the eyes.','<b>Meaning.</b> Seeing the god, offering light, burning pride.'],'Part 2 is tilaka.','Light given, light returned')
src=sources([('Practice:','Common Hindu pūjā practice (upacāras, ṣoḍaśopacāra, nīrājana) as described in standard pūjā manuals and reference works; Wikipedia, “Aarti” (etymology from ārātrika, Om Jaya Jagadīśa Hare and Śraddhārām Phillauri).')],'the etymology through rātri, the feet–navel–face pattern and its counts, and the evil-eye reading of red-water ārati are commonly taught but vary; meanings marked as interpretation are teachers’ readings.','No verse text is reproduced in this part.')
finish(i,'PART 1 OF 10 · LIGHT · CAMPHOR · DARŚANA',covart('A five-wick lamp waved in a circle before a deity in a dark shrine',g(220,190,1.2,shrine2())+g(220,175,1,god('#e0a800'))+arc(220,130,44)+g(300,120,.8,plate5())),'Light given, light returned',
 'Why we do <b>ārati</b>: the name, its place in pūjā, the lamps and camphor, how the lamp is waved and received, ārati for people, the songs and the meanings.',
 'Why do we do ārati? Explained and illustrated: ārātrika and nīrājana, place in pūjā, lamps and camphor, clockwise waving, receiving the light, ārati for people, daily āratis, songs and meanings.',
 [fw,gl,name,place,what,how,recv,camph,dark,people,times,songs,st,mean,myth,endp,src])
